using System;

class Program
{
    static void Main(string[] args)
    {
        Console.WriteLine("Enter the number of strings:");
        int n = Convert.ToInt32(Console.ReadLine());

        Console.WriteLine("Enter the strings:");
        string[] strings = new string[n];
        for (int i = 0; i < n; i++)
        {
